/* Release metadata is generated by the publishing workflow. */
(() => {
  const section = document.getElementById('whats-new');
  if (!section) return;
  let release;
  function render() {
    if (!release?.tag) return;
    const zh = getLang() === 'zh';
    const inner = document.createElement('div');
    inner.className = 'whats-new-inner';
    const title = document.createElement('h2');
    title.textContent = release.tag;
    const summary = document.createElement('p');
    summary.textContent = zh ? '每一次更新，让日常更顺手。查看新功能、改进与修复。' : 'A little better, every release. Explore the latest features, improvements, and fixes.';
    const link = document.createElement('a');
    link.href = `./docs.html?lang=${getLang()}#/whats-new`;
    link.textContent = zh ? '查看更新 ↗' : 'What’s new ↗';
    inner.append(title, summary, link);
    section.replaceChildren(inner);
    section.hidden = false;
  }
  fetch('./whats-new.json', { cache: 'no-cache' })
    .then((response) => response.ok ? response.json() : null)
    .then((data) => { release = data; render(); })
    .catch(() => {});
  document.addEventListener('galdr-lang', render);
})();
